public class CircuitBreakerHealthCheck : IHealthCheck
{
    private readonly IResiliencePipelineProvider<string> _provider;

    public CircuitBreakerHealthCheck(IResiliencePipelineProvider<string> provider)
    {
        _provider = provider;
    }

    public async Task<HealthCheckResult> CheckHealthAsync(HealthCheckContext context, CancellationToken ct = default)
    {
        var pipeline = _provider.GetPipeline("order-service-pipeline");
        // Inspect circuit breaker state if exposed
        var isHealthy = await pipeline.ExecuteAsync(() => Task.FromResult(true));
        return isHealthy
            ? HealthCheckResult.Healthy()
            : HealthCheckResult.Unhealthy("Circuit breaker is open");
    }
}
